<template><div class="form-view"><div class="form-heading"><span class="form-kicker">{{ local("Welcome back") }}</span><h2>{{ local("Sign in to Creator SN") }}</h2><p>{{ local("Continue your creative journey.") }}</p></div><form @submit.prevent="submit"><label>{{ local("Account") }}<input v-model.trim="form.userid" autocomplete="username" :placeholder="local('Account or email')" /></label><label>{{ local("Password") }}<input v-model="form.pwd" type="password" autocomplete="current-password" :placeholder="local('At least 6 characters')" /></label><p v-if="error" class="error">{{ error }}</p><button class="primary-button" :disabled="loading">{{ loading ? local("Signing in…") : local("Sign in") }}</button></form><div class="form-foot"><span>{{ local("No account yet?") }}</span><router-link to="/login/register">{{ local("Register with invite code") }}</router-link></div></div></template>
<script setup>
import { reactive, ref } from "vue";import { useRoute,useRouter } from "vue-router";import { UserApi } from "@/api";import { useUserStore } from "@/stores/useUser";import { useAppStore } from "@/store";
const router=useRouter(),route=useRoute(),user=useUserStore(),form=reactive({userid:"",pwd:""}),loading=ref(false),error=ref("");
const local = useAppStore().local;
async function submit(){if(!form.userid||!form.pwd){error.value=local("Please enter account and password");return}loading.value=true;error.value="";try{const result=await UserApi.login(form);if(result.code!==200)throw new Error(result.message||local("Sign-in failed"));user.setSession(result.data);await user.loadMe().catch(()=>{});router.push(route.query.return_url||"/")}catch(e){error.value=e.message||local("Sign-in failed")}finally{loading.value=false}}
</script>
<style scoped lang="scss">.form-view{display:grid;gap:24px}.form-heading h2{margin:8px 0;font-size:28px}.form-heading p{margin:0;color:#817b93}.form-kicker{font-size:11px;color:#b25fba;letter-spacing:.16em;font-weight:800}form{display:grid;gap:16px}label{display:grid;gap:7px;font-size:13px;color:#504867;font-weight:700}input{width:100%;padding:13px 14px;border:1px solid #e1d8ee;border-radius:12px;background:rgba(255,255,255,.8);font:inherit;outline:none}input:focus{border-color:#ca83d4;box-shadow:0 0 0 4px rgba(202,131,212,.12)}.primary-button{padding:14px;border:0;border-radius:12px;background:linear-gradient(120deg,#9c69d7,#e27bc7);color:#fff;font-weight:800;font-size:15px;cursor:pointer}.primary-button:disabled{opacity:.6}.error{margin:-5px 0;color:#ba4e70;font-size:13px}.form-foot{font-size:13px;color:#817b93}.form-foot a{margin-left:6px;color:#8759b6;font-weight:700;text-decoration:none}</style>
